const GLOSSARIO = [
  { termo: "Peptídeo", def: "Cadeia curta de aminoácidos (geralmente até ~50). Cadeias maiores costumam ser chamadas de proteínas." },
  { termo: "Agonista", def: "Substância que ativa um receptor e produz uma resposta biológica." },
  { termo: "GLP-1", def: "Hormônio intestinal (incretina) que aumenta a insulina, reduz o apetite e retarda o esvaziamento do estômago." },
  { termo: "Pré-clínico", def: "Estudos feitos em células ou animais, antes dos testes em humanos." },
  { termo: "Fase 1/2/3", def: "Etapas dos ensaios clínicos: segurança (1), eficácia preliminar (2) e confirmação em grande escala (3)." },
  { termo: "ECR", def: "Ensaio clínico randomizado: padrão-ouro para avaliar eficácia de um tratamento." },
  { termo: "Titulação", def: "Ajuste gradual da dose para melhorar a tolerância, feito por profissional de saúde." },
  { termo: "WADA", def: "Agência Mundial Antidoping; mantém a lista de substâncias proibidas no esporte." },
  { termo: "ANVISA", def: "Agência Nacional de Vigilância Sanitária; regula medicamentos no Brasil." },
  { termo: "IGF-1", def: "Fator de crescimento semelhante à insulina, produzido sob estímulo do GH; usado como marcador de monitoramento." },
  { termo: "Off-label", def: "Uso de um medicamento aprovado para uma indicação diferente da registrada em bula." }
];

